### Q1. After std::move

```cpp
#include <iostream>
#include <string>
#include <utility>

int main() {
    std::string a = "hello world";
    std::string b = std::move(a);

    std::cout << "a.size()=" << a.size() << " b=" << b << '\n';
    return 0;
}
